const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=cents=>(cents/100).toLocaleString('he-IL',{minimumFractionDigits:2,maximumFractionDigits:2});const date=v=>v?new Date(v).toLocaleString('he-IL',{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Jerusalem'}):'לא ידוע';
const images={'7290004131074':'https://www.ayaakov.co.il/files/products/product41_model1_image0_2022-02-10_13-23-38.jpg','7290004127329':'https://d226b0iufwcjmj.cloudfront.net/gs1-products/1184/large/7290004127329-828771/7290004127329/2024-04-18T02-13-34-213Z.jpg','8076800195057':'https://shoppy.co.il/cdn/shop/products/barillaspaghettino5pasta_1200x1200.png?v=1641324311'};
let initialized=false,state=null,selected=[],promos=false,offset=0,total=0,requestId=0,basketRequest=0;const cache=new Map();let basket={};try{const saved=JSON.parse(localStorage.getItem('salsal-live-basket')||'{}');for(const [id,n] of Object.entries(saved))if(Number.isInteger(n)&&n>0&&n<=99)basket[id]=n;}catch{}
async function api(url,options){const r=await fetch(url,options);if(!r.ok)throw Error('הנתונים אינם זמינים כרגע');return r.json();}
function storeQuery(){return selected.join(',');}function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3000);}
let directory=null,draft=[],lastVersion='',applying=false;
const norm=v=>String(v).toLowerCase().replace(/קריית/g,'קרית').replace(/תקוה/g,'תקווה').replace(/[^א-תa-z0-9]/g,'');
function cityRecord(){const q=norm($('city').value);return directory?.localities.find(c=>norm(c.name)===q||norm(c.english)===q||(q==='תלאביב'&&c.id==='5000'));}
function matchingBranches(){if(!directory)return [];const q=norm($('city').value),city=cityRecord(),chain=$('chainFilter').value,tokens=$('branchSearch').value.trim().split(/\s+/).map(norm).filter(Boolean);return directory.stores.filter(s=>(!q||(city?s.cityId===city.id:norm(s.city).includes(q)))&&(!chain||s.chain===chain)&&tokens.every(t=>norm([s.name,s.address,s.city,s.chainName].join(' ')).includes(t)));}
function renderDirectory(){if(!directory)return;const rows=matchingBranches(),loaded=new Set(state?.stores.map(s=>s.id)||[]);$('directoryCount').textContent=`${rows.length} סניפים בתוצאות · ${directory.localities.length.toLocaleString('he-IL')} יישובים במאגר`;const limited=rows.slice(0,150);$('branchList').innerHTML=limited.length?limited.map(s=>`<label class="branch-option ${draft.includes(s.id)?'chosen':''}"><input type="checkbox" data-branch="${esc(s.id)}" ${draft.includes(s.id)?'checked':''}><span><strong>${esc(s.chainName)} · ${esc(s.name)}</strong><span>${esc(s.city)}${s.address?' · '+esc(s.address):''}</span><small>${loaded.has(s.id)?'מחירים זמינים להשוואה':'מחירים ייטענו בבחירה'}${s.cityMatch==='source-name'?' · היישוב זוהה בשם הסניף':''}</small></span></label>`).join(''):'<div class="empty"><strong>עדיין אין סניפים מחוברים לבחירה הזאת</strong>אפשר לחפש יישוב סמוך או לבחור רשת אחרת. לא יוצגו מחירים מיישוב אחר במקום.</div>';if(rows.length>150)$('branchList').insertAdjacentHTML('beforeend','<p class="picker-note">מוצגים 150 סניפים. אפשר לצמצם לפי עיר, רשת או שם הסניף.</p>');$('draftCount').textContent=`${draft.length} סניפים נבחרו מתוך 24${draft.some(id=>!rows.some(s=>s.id===id))?' · חלק מהבחירה מחוץ לחיפוש הנוכחי':''}`; $('applyBranches').disabled=!draft.length||applying;}
async function status(){try{
 const previous=lastVersion;state=await api('/api/status');lastVersion=String(state.revision)+'|'+state.lastSync;
 if(!directory){directory=await api('/api/directory');$('cities').innerHTML=directory.localities.map(c=>`<option value="${esc(c.name)}">${esc(c.english)}</option>`).join('');$('chainFilter').innerHTML='<option value="">כל הרשתות</option>'+directory.chains.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} (${c.count})</option>`).join('');}
 if(!initialized){selected=state.selectedStores||state.stores.map(s=>s.id);draft=[...selected];initialized=true;}
 $('dataNotice').innerHTML=`<span>קובצי מקור רשמיים</span><div>${directory.localities.length.toLocaleString('he-IL')} יישובים לחיפוש · ${directory.stores.length} סניפים ברשימה · ${directory.chains.filter(c=>c.count>0).length} רשתות. ${state.productCount.toLocaleString('he-IL')} מוצרים בסניפים שנטענו.</div>`;
 const missing=(state.selectedStores||[]).filter(id=>!state.stores.some(s=>s.id===id));const failed=(state.results||[]).filter(s=>selected.includes(s.id)&&s.error);
 $('loadingBranches').hidden=!state.syncing&&!missing.length&&!failed.length&&!state.syncError;
 $('loadingBranches').textContent=state.syncing?`טוען ובודק מחירים מהמקורות הרשמיים… ${state.progress?.done||0} מתוך ${state.progress?.total||selected.length} סניפים נבדקו. תוצאות נוספות יופיעו בסיום.`:missing.length?`המחירים של ${missing.length} מהסניפים שנבחרו עדיין אינם זמינים. אפשר לנסות שוב דרך בחירת הסניפים.`:failed.length||state.syncError?'חלק מהמקורות לא עודכנו בבדיקה האחרונה. מוצגים המחירים האחרונים שנקלטו.':'';
 renderStores();if(!$('branchPicker').open)renderDirectory();if(previous&&previous!==lastVersion){await render();await renderBasket();}
 }catch{$('dataNotice').textContent='אין חיבור לשרת. הנתונים המוצגים, אם ישנם, לא רועננו.';}}
function renderStores(){if(!state)return;const stores=(directory?.stores||state.stores).filter(s=>selected.includes(s.id));$('categories').innerHTML=stores.map(s=>`<button class="active" data-store="${esc(s.id)}" aria-pressed="true">${esc(s.chainName)} · ${esc(s.name)}${state.stores.some(x=>x.id===s.id)?'':' · ממתין למחירים'}</button>`).join('');$('selectionSummary').textContent=`${stores.length} סניפים נבחרו · שינוי הבחירה`; $('coverage').innerHTML=`<span>מחיר רגיל בסניפים שנבחרו · מבצעים מוצגים בנפרד בתנאיהם · בדיקה אחרונה ${esc(date(state.lastSync))}</span>`;}
async function applySelection(){if(!draft.length||applying)return;applying=true;renderDirectory();try{const result=await api('/api/selection',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({stores:draft})});selected=[...result.stores];$('branchPicker').open=false;cache.clear();await status();await render();await renderBasket();}catch(e){toast(e.message);}finally{applying=false;renderDirectory();}}
function card(p){const o=p.offers[0],max=p.offers.at(-1),hasPromo=p.offers.some(o=>o.promotions.length);return `<article class="product"><div class="product-top">${images[p.barcode]?`<img class="product-image" src="${images[p.barcode]}" alt="${esc(p.name)}" loading="lazy">`:''}<div><h3>${esc(p.name)}</h3><div class="meta">${esc(p.brand)} · ${esc(p.size)}</div><div class="barcode">${esc(p.barcode)}</div></div></div><div class="price-row"><div><div class="price-label">מחיר רגיל${p.weighted?' · לפי יחידת המקור':''}${o.stale?' · מקור ישן':''}</div><div class="price">${money(o.cents)}<small>₪</small></div><div class="chain">${esc(o.chainName)} · ${esc(o.storeName)}</div><div class="meta">קובץ: ${esc(date(o.sourcePublishedAt))}</div></div>${p.offers.length>1?`<div class="spread">${p.offers.length} סניפים<b>פער ${money(max.cents-o.cents)} ₪</b></div>`:'<div class="spread">סניף אחד בלבד</div>'}</div>${hasPromo?'<div class="promo-label">קיים מבצע · יש לבדוק תנאים</div>':''}<div class="card-actions"><button class="compare" data-detail="${esc(p.id)}">מחירים ומקורות ↗</button>${!p.weighted?`<button class="add" data-add="${esc(p.id)}" aria-label="הוספת ${esc(p.name)} לסל">＋ לסל</button>`:'<span class="meta">מוצר שקיל</span>'}</div></article>`;}
async function render(append=false){const seq=++requestId;if(!append){offset=0;$('products').setAttribute('aria-busy','true');}try{if(!selected.length){$('products').innerHTML='<div class="no-results">בחרו לפחות סניף אחד להשוואה.</div>';$('resultCount').textContent='';$('loadMore').hidden=true;return;}const data=await api('/api/products?'+new URLSearchParams({q:$('search').value,stores:storeQuery(),sort:$('sort').value,promos:promos?'1':'0',offset:String(offset)}));if(seq!==requestId)return;total=data.total;data.products.forEach(p=>cache.set(p.id,p));$('resultCount').textContent=`${total.toLocaleString('he-IL')} מוצרים`;const content=data.products.map(card).join('');if(append)$('products').insertAdjacentHTML('beforeend',content);else $('products').innerHTML=content||'<div class="no-results">לא נמצאו מוצרים בנתונים של הסניפים שנבחרו.<br>אפשר לשנות את החיפוש או לבחור סניפים נוספים.</div>';offset+=data.products.length;$('loadMore').hidden=offset>=total;$('allNav').classList.toggle('nav-active',!promos);$('promoNav').classList.toggle('nav-active',promos);}catch(e){if(seq===requestId){$('products').innerHTML='<div class="no-results">לא ניתן לטעון מחירים. בדקו שהשרת המקומי פועל ונסו שוב.</div>';$('loadMore').hidden=true;}}finally{$('products').removeAttribute('aria-busy');}}
function promoMarkup(p){return `<div class="promo-detail"><strong>${esc(p.description)}</strong><p>תוקף: ${esc(date(p.start))} — ${esc(date(p.end))}<br>${p.club&&!/^0(?:\D|$)/.test(p.club)?`מועדון לפי קוד המקור: ${esc(p.club)} · `:''}${p.coupon?'נדרש קופון · ':''}כמות מינימלית במקור: ${esc(p.conditions.minQty||'לא צוינה')}${p.conditions.maxQty?' · עד '+esc(p.conditions.maxQty):''}<br>${esc(p.restrictions)}</p><small>תנאי המבצע מוצגים כפי שפורסמו; אינם מחושבים במחיר הרגיל או בסל.</small><a href="/api/source?file=${encodeURIComponent(p.sourceFile)}">קובץ המבצע המקורי ↓</a></div>`;}
async function detail(id){$('detailContent').innerHTML='<p>טוען מחירים ומקורות…</p>';$('detail').showModal();try{const p=await api('/api/product?'+new URLSearchParams({id,stores:storeQuery()}));$('detailContent').innerHTML=`<div class="eyebrow">השוואה לפי ברקוד ${esc(p.barcode)}</div><h2>${esc(p.name)}</h2><p>${esc(p.brand)} · ${esc(p.size)}</p>${p.offers.map(o=>`<section class="offer-detail"><div class="detail-row"><div><strong>${esc(o.chainName)}</strong><div class="meta">${esc(o.storeName)} · ${esc(o.city)}</div></div><strong>${money(o.cents)} ₪</strong></div><p>תיאור במקור: ${esc(o.sourceName)} · ${esc(o.sourceSize)}<br>מחיר רגיל${o.stale?' · הקובץ ישן מ־48 שעות':''}<br>פורסם בקובץ: ${esc(date(o.sourcePublishedAt))}<br>שינוי המחיר לפי הרשת: ${esc(o.priceUpdatedAt)}<br>בדיקה אחרונה: ${esc(date(o.lastCheckedAt))}${o.unitPrice?`<br>מחיר ליחידת מידה במקור: ${esc(o.unitPrice)} ₪ / ${esc(o.unit)}`:''}</p><div class="source-links"><a href="${esc(o.sourceUrl)}" target="_blank" rel="noopener noreferrer">פורטל הרשת ↗</a><a href="/api/source?file=${encodeURIComponent(o.sourceFile)}">הורדת קובץ המקור ↓</a></div><div class="source-name">${esc(o.sourceFile)}</div>${o.promotions.map(promoMarkup).join('')}</section>`).join('')}<p>פרסום מחיר אינו אישור מלאי. המחירים מתייחסים לסניפים המצוינים בלבד.</p>`;}catch{$('detailContent').innerHTML='<p>לא ניתן לטעון את פרטי המוצר כרגע.</p>';}}
async function renderBasket(){const seq=++basketRequest;const items=Object.entries(basket).map(([id,quantity])=>({id,quantity}));$('basketCount').textContent=items.reduce((a,b)=>a+b.quantity,0);try{localStorage.setItem('salsal-live-basket',JSON.stringify(basket));}catch{}for(const item of items)if(!cache.has(item.id)){try{cache.set(item.id,await api('/api/product?id='+encodeURIComponent(item.id)));}catch{}}if(seq!==basketRequest)return;$('basketItems').innerHTML=items.length?items.map(i=>`<div class="basket-item"><strong>${esc(cache.get(i.id)?.name||i.id)}</strong><div class="quantity"><button data-change="${esc(i.id)}" data-delta="-1" aria-label="הפחתת כמות">−</button><span>${i.quantity}</span><button data-change="${esc(i.id)}" data-delta="1" aria-label="הוספת כמות">+</button></div></div>`).join(''):'<div class="empty"><strong>מה קונים היום?</strong>הוסיפו מוצרים כדי להשוות<br>את עלות הסל באותו סניף.</div>';$('basketTotals').innerHTML='';if(!items.length||!selected.length)return;try{const result=await api('/api/basket',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items,stores:selected})});if(seq!==basketRequest)return;const eligible=result.stores.filter(s=>s.complete&&!s.stale),best=eligible.length>1&&selected.every(id=>state.stores.some(s=>s.id===id))?Math.min(...eligible.map(s=>s.cents)):null;$('basketTotals').innerHTML='<div class="total-heading">סל לפי מחיר רגיל · לפני מבצעים</div>'+result.stores.map(s=>`<div class="total-row ${s.complete&&!s.stale&&s.cents===best?'best':''}"><div>${esc(s.chainName)}<div class="meta">${esc(s.name)}</div>${s.complete?'':`<small>חסרים ${s.missing.length} מוצרים · אין סכום להשוואה</small>`}${s.stale?'<small>נתוני מקור ישנים</small>':''}</div><b>${s.complete?money(s.cents)+' ₪':'—'}</b></div>`).join('');}catch{$('basketTotals').textContent='חישוב הסל אינו זמין כרגע.';}}
function change(id,delta){if(delta>0&&Object.keys(basket).length>=100&&!basket[id])return toast('אפשר להשוות עד 100 מוצרים בסל');basket[id]=Math.min(99,(basket[id]||0)+delta);if(basket[id]<=0)delete basket[id];renderBasket();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.add){change(b.dataset.add,1);toast('נוסף לסל');}if(b.dataset.detail)detail(b.dataset.detail);if(b.dataset.change)change(b.dataset.change,Number(b.dataset.delta));if(b.dataset.store){$('branchPicker').open=true;draft=[...selected];renderDirectory();}});let timer;$('search').oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>render(),220);};$('sort').onchange=()=>render();$('city').oninput=()=>{$('branchPicker').open=true;renderDirectory();};$('city').onchange=()=>{if(cityRecord()||!$('city').value.trim()){$('representativeStores').click();}};$('chainFilter').onchange=renderDirectory;$('branchSearch').oninput=renderDirectory;
$('branchList').onchange=e=>{const id=e.target.dataset.branch;if(!id)return;if(e.target.checked){if(draft.length>=24){e.target.checked=false;toast('אפשר להשוות עד 24 סניפים בכל פעם');return;}draft.push(id);}else draft=draft.filter(x=>x!==id);renderDirectory();$('branchList').querySelector('[data-branch="'+CSS.escape(id)+'"]')?.focus();};
$('representativeStores').onclick=()=>{const seen=new Set();draft=matchingBranches().filter(s=>{if(seen.has(s.chain))return false;seen.add(s.chain);return true;}).slice(0,24).map(s=>s.id);renderDirectory();};$('clearDraft').onclick=()=>{draft=[];renderDirectory();};$('applyBranches').onclick=applySelection;$('branchPicker').ontoggle=()=>{if($('branchPicker').open)renderDirectory();};
$('loadMore').onclick=()=>render(true);$('allNav').onclick=()=>{promos=false;render();};$('promoNav').onclick=()=>{promos=true;render();};$('clear').onclick=()=>{basket={};renderBasket();};document.querySelector('.close').onclick=()=>$('detail').close();$('sourcesBtn').onclick=()=>{$('detailContent').innerHTML=`<h2>מחירים שאפשר לבדוק</h2><p>הנתונים נקראים מקובצי מחירים ומבצעים רשמיים של הרשתות. כל מחיר משויך לברקוד ולסניף מסוים, ובמסך פרטי המוצר אפשר להוריד את הקובץ שממנו נקרא.</p><p>השרת בודק קבצים חדשים כל 15 דקות, כל עוד הוא פועל והמחשב מחובר. הרשת קובעת מתי מתפרסם מידע חדש. תאריך שינוי מחיר יכול להיות ישן גם בקובץ חדש, אם המחיר לא השתנה.</p><p>הסל מחושב במחירים רגילים בלבד. מבצעי מועדון, כמות וקופון מוצגים בנפרד עם תוקף ותנאים. אין כרגע חישוב אוטומטי של זכאות והנחות.</p><p>מאגר החיפוש מכיל ${directory?.localities.length||0} יישובים מתוך רשימת היישובים הממשלתית, ו־${directory?.stores.length||0} סניפים מתוך קובצי הרשתות. מחיריהם של הסניפים שנבחרו נטענים לפי הצורך. עצם הופעת יישוב בחיפוש אינה מעידה שיש בו סניף מחובר. קובצי הרשתות עשויים לכלול סניפים ישנים או כתובות חסרות.</p>`;$('detail').showModal();};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('detail').open){e.preventDefault();$('search').focus();}});
async function init(){await status();await render();await renderBasket();}init();setInterval(status,10000);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'add_products_to_basket',description:'Add verified product IDs to the visible shopping list. Does not purchase; basket uses regular prices excluding promotions.',inputSchema:{type:'object',properties:{items:{type:'array',items:{type:'object',properties:{id:{type:'string'},quantity:{type:'integer',minimum:1,maximum:99}},required:['id','quantity']}}},required:['items']},execute:async input=>{if(!Array.isArray(input?.items)||input.items.length>100||!input.items.every(i=>typeof i.id==='string'&&Number.isInteger(i.quantity)&&i.quantity>0&&i.quantity<=99))throw Error('Invalid items');if(new Set([...Object.keys(basket),...input.items.map(i=>i.id)]).size>100)throw Error('Basket limit is 100 products');const products=await Promise.all(input.items.map(i=>api('/api/product?id='+encodeURIComponent(i.id))));if(products.some(p=>p.weighted))throw Error('Weighted products are not supported in basket');for(let i=0;i<products.length;i++)cache.set(products[i].id,products[i]);for(const i of input.items)basket[i.id]=Math.min(99,(basket[i.id]||0)+i.quantity);await renderBasket();return {basket};}})).catch(()=>{});}catch{}}
